class Pipeline:
    def __init__(self, data):
        self.data = data

    def filter_nulls(self, data):
        return [item for item in data if item is not None]

    def normalize_strings(self, data):
        return [item.strip().lower() if isinstance(item, str) else item for item in data]

    def deduplicate(self, data):
        seen = set()
        return [item for item in data if not (item in seen or seen.add(item))]

    def sort(self, data):
        return sorted(data)

    def pipe(self, *funcs):
        result = self.data
        for func in funcs:
            result = func(result)
        return result

    def run(self):
        return self.pipe(self.filter_nulls, self.normalize_strings, self.deduplicate, self.sort)
